def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'
    if n == 99:
        return 'D'

    opp_d = 0
    my_d = 0
    for a, b in history:
        if b == 'D':
            opp_d += 1
        if a == 'D':
            my_d += 1

    last_my, last_opp = history[-1]

    recent = history[-4:] if n >= 4 else history
    recent_my_d = 0
    recent_opp_d = 0
    for a, b in recent:
        if a == 'D':
            recent_my_d += 1
        if b == 'D':
            recent_opp_d += 1

    if opp_d <= max(2, n // 10):
        return 'C'

    if opp_d * 2 > n:
        return 'D'

    if last_opp == 'D':
        if last_my == 'C' and recent_my_d >= 2 and recent_opp_d >= 2:
            return 'C'
        if recent_my_d >= 2 and recent_opp_d >= 2:
            return 'C'
        return 'D'

    if last_my == 'D':
        return 'C'

    return 'C'
